package fft

import "github.com/go-fft/fft/internal/kernels"

// fused256Enabled is whether a fused plan of 256 points runs the one-kernel
// transform (kernels.Fused256, generated by internal/genfused256): two 16x16
// passes with every value in a zmm register inside each pass, the twiddles
// between them folded into the first. A variable so the tests can run both
// routes where it is on, and so that the plan cache of another configuration is
// not poisoned (plans record the choice when built).
var fused256Enabled = kernels.Fused256On

// fused256Route reports whether a fused plan of n points takes the kernel.
// Exact and NoFMA plans never do (their arithmetic is not fused), and nor does
// any CPU but the Zen 4 the kernel was measured on (go-fft/fft#124).
func fused256Route(n int) bool { return n == 256 && fused256Enabled }
